content.xhtml:p:
In this example function block with the same functionality 
is created using all five IEC 61131-3 programing languages:
- IL;
- FBD;
- LD;
- ST;
- SFC.




Function block is a counter with reset control input.
If reset is True counter value is reset to the value defined by
global configuration constant ResetCounterValue. 
If reset is False, counter is incremented every cycle.

ST.xhtml:p:
IF Reset THEN
  Cnt := ResetCounterValue;
ELSE
  Cnt := Cnt + 1;
END_IF;

Out := Cnt;

(* FOR loop test s *)

RESULT := 'Single iteration FOR loop'; 

FOR I:= 1 TO 1 DO
  K := K + 1;
END_FOR;

IF NOT (K = 1) THEN RETURN; END_IF;

RESULT := 'Single iteration FOR BY loop'; 

K := 0;
FOR I:= 1 TO 2 BY 2 DO
  K := K + 1;
END_FOR;

IF NOT (K = 1) THEN RETURN; END_IF;


RESULT := 'By 2 FOR loop'; 

J := TRUE;
FOR I:= 2 TO 10 BY 2 DO
  WORDS[I] := I;
END_FOR;

J := J AND WORDS[1] = 0;
J := J AND WORDS[2] = 2;
J := J AND WORDS[3] = 0;
J := J AND WORDS[4] = 4;
J := J AND WORDS[5] = 0;
J := J AND WORDS[6] = 6;
J := J AND WORDS[7] = 0;
J := J AND WORDS[8] = 8;
J := J AND WORDS[9] = 0;
J := J AND WORDS[10] = 10;

IF NOT J THEN RETURN; END_IF;

RESULT := 'By 2 FOR loop with CONTINUE'; 

J := TRUE;
FOR I:= 1 TO 10 BY 2 DO
  IF I = 5 THEN
    CONTINUE;
  END_IF;
  WORDS[I] := I;
END_FOR;

J := J AND WORDS[1] = 1;
J := J AND WORDS[2] = 2;
J := J AND WORDS[3] = 3;
J := J AND WORDS[4] = 4;
J := J AND WORDS[5] = 0;
J := J AND WORDS[6] = 6;
J := J AND WORDS[7] = 7;
J := J AND WORDS[8] = 8;
J := J AND WORDS[9] = 9;
J := J AND WORDS[10] = 10;

IF NOT J THEN RETURN; END_IF;

(* TODO: CONTINUE EXIT WHILE REPEAT *)


RESULT := 'OK';

