RESULT := 'OK';

(* Drives the two LD function blocks over their full truth tables.
   Both rungs have parallel branches of unequal length, which is the shape that
   used to raise TypeError in PLCGenerator.FactorizePaths on Python 3. *)

RESULT := 'LDUnequalBranches';
J := TRUE;
(* Y := (A AND NOT B) OR C *)
U(A := FALSE, B := FALSE, C := FALSE); J := J AND (U.Y = FALSE);
U(A := FALSE, B := FALSE, C := TRUE);  J := J AND (U.Y = TRUE);
U(A := FALSE, B := TRUE,  C := FALSE); J := J AND (U.Y = FALSE);
U(A := FALSE, B := TRUE,  C := TRUE);  J := J AND (U.Y = TRUE);
U(A := TRUE,  B := FALSE, C := FALSE); J := J AND (U.Y = TRUE);
U(A := TRUE,  B := FALSE, C := TRUE);  J := J AND (U.Y = TRUE);
U(A := TRUE,  B := TRUE,  C := FALSE); J := J AND (U.Y = FALSE);
U(A := TRUE,  B := TRUE,  C := TRUE);  J := J AND (U.Y = TRUE);
IF NOT J THEN RETURN; END_IF;

RESULT := 'LDNestedBranches';
(* Y := A OR (A AND B) OR (A AND B AND C), which reduces to A *)
N(A := FALSE, B := FALSE, C := FALSE); J := J AND (N.Y = FALSE);
N(A := FALSE, B := FALSE, C := TRUE);  J := J AND (N.Y = FALSE);
N(A := FALSE, B := TRUE,  C := FALSE); J := J AND (N.Y = FALSE);
N(A := FALSE, B := TRUE,  C := TRUE);  J := J AND (N.Y = FALSE);
N(A := TRUE,  B := FALSE, C := FALSE); J := J AND (N.Y = TRUE);
N(A := TRUE,  B := FALSE, C := TRUE);  J := J AND (N.Y = TRUE);
N(A := TRUE,  B := TRUE,  C := FALSE); J := J AND (N.Y = TRUE);
N(A := TRUE,  B := TRUE,  C := TRUE);  J := J AND (N.Y = TRUE);
IF NOT J THEN RETURN; END_IF;

RESULT := 'OK';
